mapper.select:
SELECT COUNT(*)
FROM shop
WHERE shop_name=#{shopName}

mapper.update:
UPDATE shop SET
shop_name = #{shopName}
,telephone = #{telephone}
,shop_stat_ty_cd = #{shopStatTyCd}
,lat = #{lat}
,lot = #{lot}
WHERE
shop_id = #{shopId}

mapper.select:
SELECT
COUNT(*)
FROM
cstmr_shop_hstry
WHERE
shop_id=#{shopId}
and cstmr_id=#{cstmrId}
and date(visit_time)=date(now());

mapper.insert:
INSERT INTO cstmr_shop_hstry
(
cstmr_id
, shop_id
, staff_id
)
VALUES (
#{cstmrId}
, #{shopId}
, #{staffId}
)

mapper.delete:
DELETE
FROM
cstmr_shop_hstry
WHERE
shop_id = #{shopId}
and date(visit_time) <= subdate(current_date,2);

mapper.select:
SELECT COUNT(*)
FROM
shop_new_cstmr
WHERE
shop_id=#{shopId}
and join_date=#{joinDate}

mapper.update:
UPDATE shop_new_cstmr SET
join_count=#{joinCount}
WHERE
shop_id = #{shopId}
AND join_date = #{joinDate}
